<template>
 <el-drawer title="固定套装组成" :visible.sync="visible" size="min(900px,96vw)" append-to-body :wrapper-closable="false" custom-class="goods-bundle-drawer"><div class="bundle-editor" v-loading="loading||saving">
 <h3>{{ goods.goodsName }} · {{ goods.skuSn }}</h3><el-alert title="虚拟套装按组件履约；实物套装通过组装形成成品库存，订单直接扣减成品。" description="每次发布形成新版本，已有订单继续使用原快照。库存模式发布后固定；实物套装组成固定，调整配方须使用新的SKU。" type="info" :closable="false" show-icon/>
 <p><el-radio-group v-model="form.inventory_mode" :disabled="form.revision>0"><el-radio label="VIRTUAL">虚拟套装（扣组件）</el-radio><el-radio label="STOCKED">实物套装（扣成品）</el-radio></el-radio-group></p><p>组成版本 {{ form.revision||'尚未发布' }} <el-switch v-model="form.enabled" :active-value="1" :inactive-value="0" active-text="启用套装组成"/></p>
 <el-table :data="form.components" empty-text="添加普通SKU作为套装组件"><el-table-column label="组件商品 / SKU" min-width="260"><template slot-scope="s"><b>{{ s.row.goods_name }}</b><p>{{ s.row.sku_sn }}</p></template></el-table-column><el-table-column label="每套数量（件）" min-width="165"><template slot-scope="s"><el-input-number v-model="s.row.quantity" :min="1" :max="100000" :precision="0" size="small"/></template></el-table-column><el-table-column label="操作" width="160"><template slot-scope="s"><router-link :to="{path:'/oms-inventory/productInventory',query:{skuSn:s.row.sku_sn}}">组件库存</router-link><el-button v-hasPermi="['goods:info:edit']" type="text" @click="form.components.splice(s.$index,1)">移除</el-button></template></el-table-column></el-table>
 <el-button v-hasPermi="['goods:info:edit']" size="small" icon="el-icon-plus" @click="picker=true">选择组件SKU</el-button><p class="hint">1套包含 {{ form.components.length }} 种SKU、{{ pieces }} 件。金额属于销售套装；组件不重复记录销售金额。</p>
 <el-alert v-if="error" :title="error" type="warning" :closable="false"/><div class="actions"><el-button v-if="form.inventory_mode==='STOCKED'&&form.revision" @click="$router.push({path:'/oms-inventory/kitProcess',query:{sku:goods.skuSn}});visible=false">组装／拆卸</el-button><el-button @click="visible=false">关闭</el-button><el-button v-hasPermi="['goods:info:edit']" type="primary" :disabled="!form.components.length||loading" :loading="saving" @click="save">发布套装组成</el-button></div>
 </div><el-dialog title="选择普通组件SKU" :visible.sync="picker" width="min(800px,95vw)" append-to-body><el-input v-model.trim="keyword" placeholder="商品名称或完整SKU" @keyup.enter.native="search"><el-button slot="append" icon="el-icon-search" @click="search"/></el-input><el-table :data="choices" v-loading="searching"><el-table-column prop="goodsName" label="商品名称"/><el-table-column prop="skuSn" label="SKU"/><el-table-column label="操作" width="85"><template slot-scope="s"><el-button type="text" :disabled="form.components.some(c=>c.sku_sn===s.row.skuSn)" @click="choose(s.row)">选择</el-button></template></el-table-column></el-table><p class="hint">仅显示普通SKU，最多50种组件。</p></el-dialog></el-drawer>
</template>
<script>
import { getBundle,saveBundle,listInfo } from '@/api/goods/info'
export default {name:'GoodsBundle',data:()=>({visible:false,loading:false,saving:false,goods:{},form:{revision:0,enabled:1,inventory_mode:'VIRTUAL',components:[]},error:'',picker:false,keyword:'',choices:[],searching:false,sequence:0}),computed:{pieces(){return this.form.components.reduce((n,c)=>n+Number(c.quantity||0),0)}},methods:{async open(goods){const seq=++this.sequence;this.goods=goods;this.visible=true;this.loading=true;this.error='';try{const r=await getBundle(goods.id);if(seq===this.sequence)this.form=r.data}catch(_){this.error='套装组成加载失败，请重新打开'}finally{if(seq===this.sequence)this.loading=false}},async search(){if(!this.keyword)return;this.searching=true;try{const exact=(await listInfo({skuSn:this.keyword,isPackage:0,isFd:0,pageNum:1,pageSize:20})).rows;this.choices=exact.length?exact:(await listInfo({goodsName:this.keyword,isPackage:0,isFd:0,pageNum:1,pageSize:20})).rows}finally{this.searching=false}},choose(row){if(this.form.components.length>=50)return this.$message.warning('最多50种组件');this.form.components.push({sku_sn:row.skuSn,goods_name:row.goodsName,quantity:1});this.picker=false},async save(){if(this.saving)return;this.saving=true;try{this.form=(await saveBundle(this.goods.id,this.form)).data;this.$message.success('套装组成已发布，已有订单快照保持原版本')}finally{this.saving=false}}}}
</script>
<style scoped>.bundle-editor{padding:0 24px 24px}.bundle-editor .el-alert{margin:16px 0}.hint{font-size:12px;color:#7b8ba1;line-height:1.8}.actions{display:flex;justify-content:flex-end;gap:12px;padding-top:20px}.el-switch{margin-left:18px}</style>
